const assignedTargets = PLAYABLE_TARGETS.filter(({ batchId }) => ASSIGNED_BATCH_IDS.has(batchId));
const seedsByCategorySetId = new Map(CATEGORY_SEEDS.map((seed) => [seed.categorySetId, seed]));
const rawCategories: readonly PlayableCategory[] = assignedTargets.map((target) => {
  const seed = seedsByCategorySetId.get(target.categorySetId);
  if (seed === undefined) throw new Error(`Missing authored seed for ${target.categorySetId}`);
  return { ...target, name: seed.name, questions: seed.questions };
});

export const PACKS_09_TO_12_CATEGORIES: readonly PlayableCategory[] = validatePlayableCorpus(rawCategories, assignedTargets);
